```css
/* Token Radar — Warm Playful 'Not-Portfolio' Aesthetic */
:root {
  --bg-cream: #FFF8E7;
  --bg-white: #FFFFFF;
  --text-black: #111111;
  --text-muted: #555555;
  --text-dim: #777777;

  /* Accents */
  --accent-orange: #FF5A2E;
  --accent-yellow: #FFC53D;
  --accent-green: #09825d;
  --accent-red: #c92a2a;

  /* Borders */
  --border-hairline: rgba(17, 17, 17, 0.12);
  --border-subtle: rgba(17, 17, 17, 0.2);
  --border-pill: #111111;

  /* Hover & Highlight */
  --row-hover: rgba(255, 90, 46, 0.08);
  --pill-hover: rgba(255, 90, 46, 0.12);

  /* Terminal Card Palette */
  --term-bg: #1E1E1E;
  --term-bar: #161616;
  --term-text: #E5E5E5;
  --term-dim: #888888;
  --term-border: rgba(255, 255, 255, 0.12);
  --term-dot-red: #FF5F56;
  --term-dot-yellow: #FFBD2E;
  --term-dot-green: #27C93F;

  /* Typography Stacks */
  --font-display: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Nunito", "Arial Rounded MT Bold", sans-serif;
  --font-mono: ui-monospace, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
}

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  background-color: var(--bg-cream);
  color: var(--text-black);
  color-scheme: light;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--bg-cream);
  color: var(--text-black);
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Accessibility Skip Link */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 16px;
  background: var(--accent-orange);
  color: #fff;
  padding: 8px 16px;
  font-weight: 700;
  border-radius: 9999px;
  border: 1.5px solid var(--border-pill);
  z-index: 1000;
  text-decoration: none;
}
.skip-link:focus {
  top: 16px;
}

:focus-visible {
  outline: 2px solid var(--accent-orange) !important;
  outline-offset: 2px;
}

.data-table tbody tr:focus-visible {
  outline: 2px solid var(--accent-orange) !important;
  outline-offset: -2px;
  background-color: var(--row-hover);
}

.pill-control:focus-visible,
.pill-toggle:focus-visible,
.sort-btn:focus-visible,
.term-close-btn:focus-visible,
.reset-btn:focus-visible,
.load-more-btn:focus-visible {
  outline: 2px solid var(--accent-orange) !important;
  outline-offset: 2px;
}

/* Shell Layout */
.shell {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 20px 48px;
}

/* Top Navbar / Wordmark */
.top-nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border-hairline);
}

.wordmark-group {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: -0.02em;
  text-transform: lowercase;
}

.wordmark-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--accent-orange);
  display: inline-block;
  box-shadow: 0 0 0 2px rgba(255, 90, 46, 0.2);
}

.wordmark-text {
  color: var(--text-black);
}

.nav-pills {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.nav-pill {
  display: inline-flex;
  align-items: center;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  background: var(--bg-white);
  padding: 4px 12px;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: lowercase;
  font-weight: 600;
  color: var(--text-black);
  box-shadow: 1px 1px 0 var(--border-pill);
}

.nav-pill.pill-yellow {
  background: var(--accent-yellow);
}

/* Hero Section */
.hero-section {
  text-align: center;
  padding: 56px 16px 44px;
}

.hero-content {
  max-width: 860px;
  margin: 0 auto;
}

.hero-headline {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 7vw, 4.8rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 0.98;
  margin: 0 0 16px;
  text-transform: lowercase;
  color: var(--text-black);
}

.accent-orange {
  color: var(--accent-orange);
}

.hero-tagline {
  font-family: var(--font-mono);
  font-size: clamp(12px, 1.8vw, 15px);
  color: var(--text-muted);
  text-transform: lowercase;
  margin: 0 auto 32px;
  max-width: 620px;
  line-height: 1.45;
}

/* Stat Chips / Pill Badges */
.hero-stat-chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 8px;
}

.stat-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  background: var(--bg-white);
  padding: 7px 16px;
  font-family: var(--font-mono);
  font-size: 12px;
  text-transform: lowercase;
  font-weight: 600;
  color: var(--text-black);
  box-shadow: 2px 2px 0 var(--border-pill);
  transition: transform 0.12s, box-shadow 0.12s;
}

.stat-chip:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3px 3px 0 var(--border-pill);
}

.stat-chip.pill-yellow {
  background: var(--accent-yellow);
}

.stat-chip.pill-orange {
  background: var(--bg-white);
  border-color: var(--border-pill);
}

.chip-sym {
  font-size: 11px;
}

.chip-label {
  color: var(--text-muted);
  font-weight: 500;
}

.chip-val {
  color: var(--text-black);
  font-weight: 700;
}

/* Summary Stat Strip */
.stat-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin: 0 auto 32px;
  max-width: 1100px;
}

@media (max-width: 960px) {
  .stat-strip {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .stat-strip {
    grid-template-columns: 1fr;
  }
}

.stat-pill-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 18px 20px;
  background: var(--bg-white);
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  box-shadow: 2.5px 2.5px 0 var(--border-pill);
  text-align: center;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.stat-pill-card:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3.5px 3.5px 0 var(--border-pill);
}

.stat-pill-num {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 2.6vw, 2.5rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.035em;
  color: var(--text-black);
  margin-bottom: 5px;
}

.stat-pill-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: lowercase;
  letter-spacing: -0.01em;
}

/* Controls Panel */
.controls-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 20px 0;
  border-top: 1px solid var(--border-hairline);
  border-bottom: 1px solid var(--border-hairline);
  margin-bottom: 24px;
}

.control-group {
  display: flex;
  align-items: center;
}

.control-label {
  font-family: var(--font-mono);
  font-size: 12px;
  text-transform: lowercase;
  font-weight: 600;
  margin-right: 8px;
  color: var(--text-muted);
}

.search-wrap {
  position: relative;
  flex: 1 1 240px;
  min-width: 220px;
}

.control-glyph {
  position: absolute;
  left: 14px;
  color: var(--text-muted);
  font-size: 14px;
  pointer-events: none;
}

.pill-control {
  font-family: var(--font-mono);
  font-size: 12px;
  text-transform: lowercase;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  background: var(--bg-white);
  color: var(--text-black);
  padding: 8px 16px;
  outline: none;
  box-shadow: 1.5px 1.5px 0 var(--border-pill);
  transition: border-color 0.15s, box-shadow 0.15s;
}

.pill-control:focus {
  border-color: var(--accent-orange);
  box-shadow: 2px 2px 0 var(--accent-orange);
}

.pill-input {
  width: 100%;
  padding-left: 34px;
}

.pill-input::placeholder {
  color: var(--text-dim);
}

.pill-select {
  padding-right: 28px;
  cursor: pointer;
}

.toggle-pills {
  display: inline-flex;
  gap: 6px;
}

.pill-toggle {
  font-family: var(--font-mono);
  font-size: 12px;
  text-transform: lowercase;
  font-weight: 600;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  padding: 8px 16px;
  background: var(--bg-white);
  color: var(--text-black);
  cursor: pointer;
  box-shadow: 1.5px 1.5px 0 var(--border-pill);
  transition: background-color 0.15s, color 0.15s, transform 0.12s;
}

.pill-toggle:hover {
  background: var(--pill-hover);
}

.pill-toggle.active {
  background: var(--border-pill);
  color: #ffffff;
}

.results-badge {
  font-family: var(--font-mono);
  font-size: 11.5px;
  text-transform: lowercase;
  font-weight: 700;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  padding: 7px 15px;
  background: var(--accent-yellow);
  color: var(--text-black);
  box-shadow: 1.5px 1.5px 0 var(--border-pill);
  margin-left: auto;
  white-space: nowrap;
}

/* Board Table */
.board-panel {
  background: transparent;
  outline: none;
}

.table-responsive {
  width: 100%;
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  text-align: left;
  font-family: var(--font-mono);
  font-size: 12.5px;
}

.data-table thead {
  position: sticky;
  top: 0;
  z-index: 15;
}

.data-table thead th {
  position: sticky;
  top: 0;
  z-index: 15;
  background-color: rgba(255, 248, 231, 0.94);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 12px 14px;
  border-bottom: 2px solid var(--border-pill);
  font-size: 11.5px;
  text-transform: lowercase;
  font-weight: 700;
  color: var(--text-black);
  white-space: nowrap;
}

.sort-btn {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  text-transform: lowercase;
}

.sort-indicator {
  font-size: 10px;
  color: var(--accent-orange);
  min-width: 12px;
  display: inline-block;
}

.data-table tbody tr {
  border-bottom: 1px solid var(--border-hairline);
  cursor: pointer;
  transition: background-color 0.12s;
}

.data-table tbody tr:hover {
  background-color: var(--row-hover);
}

.data-table tbody td {
  padding: 13px 14px;
  vertical-align: middle;
}

/* Rank column */
.td-rank {
  width: 68px;
}

.rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 12px;
  min-width: 38px;
  padding: 3px 8px;
  border-radius: 9999px;
  color: var(--text-black);
}

/* Top 3 rank highlighting */
.rank-badge.rank-1 {
  background: var(--accent-orange);
  color: #ffffff;
  border: 1.5px solid var(--border-pill);
  box-shadow: 1.5px 1.5px 0 var(--border-pill);
  font-weight: 900;
}

.rank-badge.rank-top {
  color: var(--accent-orange);
  font-weight: 800;
  border: 1.5px solid var(--accent-orange);
  background: rgba(255, 90, 46, 0.08);
}

/* Protocol Name column */
.proto-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.proto-name-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.proto-name {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 800;
  color: var(--text-black);
  letter-spacing: -0.02em;
}

.star-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1.5px solid var(--border-pill);
  border-radius: 9999px;
  background: var(--accent-yellow);
  color: var(--text-black);
  padding: 1px 7px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-transform: lowercase;
}

.proto-chains {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-muted);
  text-transform: lowercase;
}

/* Category column */
.category-pill {
  display: inline-block;
  border: 1px solid var(--border-subtle);
  border-radius: 9999px;
  padding: 3px 10px;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: lowercase;
  background: rgba(255, 197, 61, 0.22);
  color: var(--text-black);
  white-space: nowrap;
}

/* Numeric Columns */
.th-tvl, .td-tvl,
.th-growth, .td-growth,
.th-age, .td-age,
.th-odds, .td-odds,
.th-implied, .td-implied {
  text-align: right;
}

.th-quality, .td-quality {
  text-align: center;
  width: 88px;
}

.cell-num {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: var(--text-black);
}

.growth-pos {
  color: var(--accent-green);
  font-weight: 600;
}

.growth-neg {
  color: var(--accent-red);
  font-weight: 600;
}

.growth-zero {
  color: var(--text-dim);
}

/* Token Odds Cell */
.odds-cell-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  width: 100%;
}

.odds-num {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text-black);
  min-width: 44px;
  text-align: right;
}

.odds-bar-track {
  width: 48px;
  height: 5px;
  background: rgba(17, 17, 17, 0.12); /* 12%-black track */
  border-radius: 9999px;
  overflow: hidden;
  flex-shrink: 0;
}

.odds-bar-fill {
  height: 100%;
  background: var(--accent-orange);
  border-radius: 9999px;
}

/* Data Quality Cell */
.dq-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: 9999px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-white);
  font-size: 10.5px;
  font-weight: 600;
  text-transform: lowercase;
  color: var(--text-black);
}

.dq-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.dq-dot-green { background-color: var(--accent-green); }
.dq-dot-yellow { background-color: var(--accent-yellow); }
.dq-dot-red { background-color: var(--accent-red); }

/* Implied Value Cell */
.implied-cell-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.implied-val-text {
  font-family: var(--font-mono);
  font-weight: 800;
  font-size: 13px;
  color: var(--text-black);
  font-variant-numeric: tabular-nums;
}

.implied-bar-bg {
  width: 90px;
  height: 4px;
  background: rgba(17, 17, 17, 0.08);
  border-radius: 9999px;
  overflow: hidden;
}

.implied-bar-fill {
  height: 100%;
  background: var(--accent-orange);
  border-radius: 9999px;
}

/* Empty State */
.empty-state {
  text-align: center;
  padding: 56px 20px;
  margin: 32px 0;
  border: 1.5px dashed var(--border-pill);
  border-radius: 20px;
  background: var(--bg-white);
}

.empty-glyph {
  font-size: 36px;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.empty-title {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 900;
  text-transform: lowercase;
  margin: 0 0 8px;
}

.empty-sub {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-muted);
  text-transform: lowercase;
  margin: 0 0 20px;
}

.reset-btn, .load-more-btn {
  cursor: pointer;
  font-weight: 700;
  padding: 10px 24px;
}

.load-more-wrap {
  display: flex;
  justify-content: center;
  padding: 36px 0 12px;
}

/* Footer */
.bottom-footer {
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid var(--border-hairline);
  text-align: center;
}

.quality-legend {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 14px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text-muted);
  text-transform: lowercase;
}

.legend-title {
  font-weight: 700;
  color: var(--text-black);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-sep {
  color: var(--text-dim);
}

.footer-text {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text-muted);
  text-transform: lowercase;
  margin: 0;
  line-height: 1.6;
}

/* ==========================================================================
   Dark Terminal Card (Modal Detail View)
   ========================================================================== */
.terminal-modal {
  border: none;
  padding: 0;
  background: transparent;
  max-width: 880px;
  width: 94%;
  border-radius: 20px;
  overflow: visible;
}

.terminal-modal::backdrop {
  background: rgba(17, 17, 17, 0.68);
  backdrop-filter: blur(4px);
}

.terminal-card {
  background: var(--term-bg);
  color: var(--term-text);
  border-radius: 20px;
  border: 1px solid var(--term-border);
  box-shadow: 0 28px 64px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(0, 0, 0, 0.4);
  overflow: hidden;
  font-family: var(--font-mono);
}

.term-title-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  background: var(--term-bar);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  user-select: none;
}

.term-dots {
  display: flex;
  align-items: center;
  gap: 8px;
}

.term-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
}

.term-dot.dot-red {
  background: var(--term-dot-red);
}

.term-dot.dot-yellow {
  background: var(--term-dot-yellow);
}

.term-dot.dot-green {
  background: var(--term-dot-green);
}

.term-window-title {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--term-dim);
  text-transform: lowercase;
  font-weight: 500;
}

.term-close-btn {
  background: none;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: var(--term-dim);
  font-family: var(--font-mono);
  font-size: 11px;
  padding: 3px 8px;
  cursor: pointer;
  text-transform: lowercase;
  transition: all 0.15s;
}

.term-close-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.3);
}

.term-body {
  padding: 22px 24px;
  max-height: 75vh;
  overflow-y: auto;
  font-size: 12.5px;
  line-height: 1.65;
}

.term-prompt-cmd {
  color: #ffffff;
  margin-bottom: 14px;
  font-weight: 600;
}

.term-cmd-glyph {
  color: var(--term-dot-green);
  margin-right: 6px;
}

.term-section-divider {
  border-top: 1px dashed rgba(255, 255, 255, 0.15);
  margin: 16px 0;
}

.term-section-header {
  color: var(--accent-yellow);
  font-weight: 700;
  text-transform: lowercase;
  margin-bottom: 8px;
}

.term-arithmetic-block {
  margin: 10px 0;
}

.term-line {
  display: flex;
  font-family: var(--font-mono);
  white-space: pre;
