        renderTable();
      });
    }

    // Load More button
    if (loadMoreBtn) {
      loadMoreBtn.addEventListener('click', function () {
        state.displayedCount += state.pageSize;
        renderTable();
      });
    }

    // Dialog close on backdrop click
    detailModal.addEventListener('click', function (e) {
      if (e.target === detailModal) {
